            check(sha(decoded[rel])==v['sha256'] and len(decoded[rel])==v['bytes'],'pre-storage raw '+p);counts['transport']+=1
        elif p in notes:counts['explicit_narrative_updates']+=1
        else:
            check(sha(cache[p])==v['sha256'] and len(cache[p])==v['bytes'],'pre-storage unchanged '+p);counts['unchanged']+=1
    check(dict(counts)=={'unchanged':2881,'explicit_narrative_updates':4,'transport':19},'prestorage counts')
    check(custody['original_manifest_sha256']==sha(m1b) and custody['stored_manifest_sha256']==sha(m2b),'custody manifest hashes')
    programs=get('stage-d/program-preservation.json')['original_programs']
