    check(sha(oldraw('stage-a/source/paths.txt'))==summary['path_list_sha256'],'native path list SHA')
    check(set(oldraw('stage-a/source/paths.txt').decode().splitlines())==keys and len(rows)==len(keys)==432,'432 native keys')
