    check(all({k:x[k] for k in ['mode','type','oid']}==tree[x['path']] for x in rows),'table tree identities')
    for ref in [FINAL,SEED,bindings['source'],bindings['p1'],bindings['fork_base']]:
        data=git('ls-tree','-r','-z',ref,'--',*sorted(keys));actual={}
        for entry in data.rstrip(b'\0').split(b'\0'):
