    text=oldraw('02-forward-audit.md').decode();table_counts={}
    for title,end in [('Provenance','Coverage'),('Coverage','Configuration inputs (12)')]:
        section=text.split('## '+title+'\n',1)[1].split('## '+end+'\n',1)[0]
        lines=[l for l in section.splitlines() if l.startswith('| projects/')];paths=[l.split(' | ')[0][2:] for l in lines]
        check(len(paths)==len(set(paths))==432 and set(paths)==keys,title+' population')
        check(all(all(c.strip() for c in re.split(r'(?<!\\)\|',l)[1:-1]) for l in lines),title+' empty cells');table_counts[title]=len(paths)
    required=['recipe_pins','selected_stack','origin','target_summary','application','upstream_status','backport_status','carrying_reason','next_owner','receipts','coverage']
    check(all(all(isinstance(x.get(k),str) and x[k].strip() for k in required) for x in rows),'nonempty evidence/owners')
    linux=sum(x['path'].endswith('.patch') and ('/patches/linux/' in x['path'] or '/packages/linux/patches/' in x['path']) for x in rows)
    check(linux==346 and kinds['config']==12 and len(rows)-linux-kinds['config']==74,'346/12/74')
    groups=get('stage-b/group-census.json');check(len({str(pathlib.PurePosixPath(x['path']).parent) for x in rows})==groups['containing_directories']==72,'72 directories')
    combos={tuple(x['buildable_by']) for x in rows};configs={v for x in rows for v in x['buildable_by']}
