    result['membership']={'rows':len(rows),'logical_lines':total,'literal_bytes_recorded':summary['bytes'],'newline_bytes_recorded':summary['newlines'],'modes':dict(modes),'kinds':dict(kinds),'groups':groups,'tables':table_counts,'source_recipe_and_selector_count':len(extra),'base_equal_rows':sum(x['base_identical'] for x in rows),'upstream_statuses':dict(collections.Counter(x['upstream']['status'] for x in rows))}

