#!/usr/bin/env python3
"""Independent immutable record comparison; never imports or executes lane code."""
import collections, hashlib, json, os, pathlib, re, stat, subprocess
ROOT=pathlib.Path(__file__).parent
REPO='/workspace/repos/pixelelated/distribution.worktrees/m6-p1-survey-641'
FINAL='676115271e9bbaa9e8db81f6de73a7b49094c5b4'
SEED='601e4694f9726b2228d3571efdb5cfc061c6d442'
AUDIT='docs/audits/2026_11_02-epic-m6-patches-unshipped/'
PUB='/workspace/tmp/m6-t43/stage-d-publication'
OBS={}; COMMANDS=[]
def sha(b): return hashlib.sha256(b).hexdigest()
def git(*args):
    argv=['git','-C',REPO,*args]; COMMANDS.append(argv)
    return subprocess.check_output(argv)
def blob(path, ref=FINAL):
    b=git('show',ref+':'+path); OBS[ref+':'+path]={'bytes':len(b),'sha256':sha(b)}; return b
def b(rel): return blob(AUDIT+rel)
def j(rel): return json.loads(b(rel))
def confined(rel):
    parts=rel.split('/'); assert all(p not in ('','.','..') for p in parts)
    fd=os.open('/',os.O_RDONLY|os.O_DIRECTORY)
    try:
        for p in PUB.strip('/').split('/')+parts[:-1]:
            n=os.open(p,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd);os.close(fd);fd=n
        out=os.open(parts[-1],os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=fd)
        try:
            info=os.fstat(out);assert stat.S_ISREG(info.st_mode) and info.st_size<10_000_000
            chunks=[]
            while True:
                part=os.read(out,65536)
                if not part:break
                chunks.append(part)
            data=b''.join(chunks)
            assert len(data)==info.st_size
        finally:os.close(out)
    finally:os.close(fd)
    OBS[PUB+'/'+rel]={'bytes':len(data),'sha256':sha(data),'regular_nofollow_confined':True}
    return data
def save(name,value):
    (ROOT/name).write_text(json.dumps(value,indent=2,sort_keys=True)+'\n')
def journal():
    # Merge hashes from independent inspection batches without saving source bytes.
    p=ROOT/'observed-hashes.json';old=json.loads(p.read_text()) if p.exists() else {};old.update(OBS);save(p.name,old)
    p=ROOT/'commands.jsonl'
    with p.open('a') as f:
        for v in COMMANDS:f.write(json.dumps(v)+'\n')

def batch(paths):
    """Read only named immutable committed records, in memory; no tree export."""
    argv=['git','-C',REPO,'cat-file','--batch'];COMMANDS.append({'argv':argv,'stdin':{'ref':FINAL,'paths':sorted(paths)}})
    proc=subprocess.Popen(argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE)
    data,_=proc.communicate(''.join(FINAL+':'+p+'\n' for p in paths).encode());assert proc.returncode==0
    pos=0;out={}
    for p in paths:
        end=data.index(b'\n',pos);header=data[pos:end].split();assert header[1]==b'blob',p
        size=int(header[2]);value=data[end+1:end+1+size];assert data[end+1+size:end+2+size]==b'\n'
        pos=end+2+size;out[p]=value
        OBS[FINAL+':'+p]={'bytes':size,'sha256':sha(value)}
    assert pos==len(data)
    return out

def main():
    assert set(os.sched_getaffinity(0))<=set(range(8,24))
    result={}; discrepancies=[]
    def check(ok,label):
        if not ok:discrepancies.append(label)
    pubbytes=confined('publication.json');check(sha(pubbytes)=='5e88d39b0b1a71ab134d788e65b8d9b5ee7dcf04a03256275f2ea2a53f2982dd','publication authorization SHA');pub=json.loads(pubbytes)
    readback=confined('checkpoint-readback.json');check(sha(readback)=='a3a9607aeeaaf8405ab75ab2fdfc8d67180b0594b9f01dd4e988ed0a6e658f66','checkpoint authorization SHA')
    m1b=confined('staged-manifest.json');m2b=confined('staged-manifest-v2.json');before=json.loads(m1b);after=json.loads(m2b)
    check(sha(m2b)==pub['manifest_sha256'],'published manifest SHA')
    changed=git('diff','--name-only','-z',SEED,FINAL).decode().strip('\0').split('\0')
    check(set(changed)==set(after) and len(after)==2932,'2932 exact committed manifest paths')
    cache=batch(sorted(after))
    def raw(rel):return cache[AUDIT+rel]
    def get(rel):return json.loads(raw(rel))
    transport=get('stage-d/transport-manifest.json'); stored=transport['stored_component'].encode();original=stored.replace(b'\\u002d',b'-',1)
    decoded={};occ=0
    for rel,v in transport['files'].items():
        value=raw(rel);n=value.count(stored);dec=value.replace(stored,original);decoded[rel]=dec;occ+=n
        check((len(value),sha(value),len(dec),sha(dec),n)==(v['stored_bytes'],v['stored_sha256'],v['raw_bytes'],v['raw_sha256'],v['occurrences']),'transport '+rel)
    check(len(decoded)==19 and occ==46,'19/46 transport totals')
    def oldraw(rel):return decoded.get(rel,raw(rel))
    for p,v in after.items():check(len(cache[p])==v['bytes'] and sha(cache[p])==v['sha256'],'committed manifest '+p)
    custody=json.loads(confined('prior-record-preservation.json'));notes=set(custody['explicit_narrative_updates']);counts=collections.Counter()
    for p,v in before.items():
        rel=p.removeprefix(AUDIT)
        if rel in decoded:
            check(sha(decoded[rel])==v['sha256'] and len(decoded[rel])==v['bytes'],'pre-storage raw '+p);counts['transport']+=1
        elif p in notes:counts['explicit_narrative_updates']+=1
        else:
            check(sha(cache[p])==v['sha256'] and len(cache[p])==v['bytes'],'pre-storage unchanged '+p);counts['unchanged']+=1
    check(dict(counts)=={'unchanged':2881,'explicit_narrative_updates':4,'transport':19},'prestorage counts')
    check(custody['original_manifest_sha256']==sha(m1b) and custody['stored_manifest_sha256']==sha(m2b),'custody manifest hashes')
    programs=get('stage-d/program-preservation.json')['original_programs']
    for p,v in programs.items():check(sha(cache[p])==v['sha256'] and len(cache[p])==v['bytes'] and before[p]==v,'original program '+p)
    check(len(programs)==14,'14 original programs')
    result['transport_and_custody']={'artifacts':len(decoded),'occurrences':occ,'prestorage':dict(counts),'new_files':len(set(after)-set(before)),'original_programs':len(programs),'notes':sorted(notes),'stored_manifest_sha256':sha(m2b),'raw_manifest_sha256':sha(m1b)}

    # Complete immutable path-change proof; no worktree source/status command.
    outside=[p for p in changed if not p.startswith(AUDIT)]
    allowed=['.github/sessions/saved-session-state-feature-m6-patches-unshipped-690.md','docs/work-logs/2026_11-work_logs/2026_11_02-work_log.md','docs/work-logs/INDEX.md']
    check(set(outside)==set(allowed),'owned paths')
    check(git('show','-s','--format=%P',FINAL).decode().strip()==SEED,'one direct seed child')
    check(not git('diff','--diff-filter=DR','--name-only',SEED,FINAL).strip(),'no deletion/rename')
    result['scope']={'final':FINAL,'seed':SEED,'outside_audit':outside,'changed_paths':len(changed),'protected_other_paths_unchanged':set(outside)==set(allowed)}

    rows=get('stage-b/table-input.json');keys={x['path'] for x in rows};tree=get('stage-a/source/tree.json');summary=get('stage-a/source/summary.json');bindings=get('stage-a/bindings.json')
    for file in ['paths.txt','rows.json','tree.json']:check(oldraw('stage-a/source/'+file)==oldraw('stage-a/seed/'+file),'source/seed '+file)
